cat > /workspace/tmp/perf.py <<'PYEOF'
import json, random, sys, time
sys.path.insert(0, '/workspace/submission')
import main as M

rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 5)
N = 256
LINKS = 512
EXT = 16
TRIALS = int(sys.argv[2]) if len(sys.argv) > 2 else 32
REPAIRS = int(sys.argv[3]) if len(sys.argv) > 3 else 7

nodes = [{'id': i, 'name': 'R%d' % i, 'external_capacity': 10**9} for i in range(N)]
# ring + random extra edges, degree <= 8
deg = [0] * N
links = []
seen = set()
for i in range(N):
    a, b = i, (i + 1) % N
    links.append({'source': a, 'target': b, 'capacity': 10**9})
    seen.add((min(a, b), max(a, b)))
    deg[a] += 1
    deg[b] += 1
while len(links) < LINKS:
    a = rng.randrange(N)
    b = rng.randrange(N)
    if a == b or deg[a] >= 8 or deg[b] >= 8:
        continue
    k = (min(a, b), max(a, b))
    if k in seen:
        continue
    seen.add(k)
    deg[a] += 1
    deg[b] += 1
    links.append({'source': a, 'target': b, 'capacity': rng.choice([10**9, 1000, 50000])})
ext_names = ['R%d' % i for i in rng.sample(range(N), EXT)]
topo = {'nodes': nodes, 'links': links, 'external_nodes': ext_names}
ext_ids = [int(x[1:]) for x in ext_names]

adj = {i: set() for i in range(N)}
for l in links:
    adj[l['source']].add(l['target'])
    adj[l['target']].add(l['source'])

def simple_path(s, d):
    # random DFS
    stack = [[s]]
    seen_local = set()
    while stack:
        p = stack.pop()
        last = p[-1]
        if last == d:
            return p
        if last in seen_local:
            continue
        seen_local.add(last)
        nbrs = list(adj[last])
        rng.shuffle(nbrs)
        for n in nbrs:
            if n not in p:
                stack.append(p + [n])
    return [s, d]

plan = {}
hops = 0
for s in ext_ids:
    for d in ext_ids:
        if s == d:
            continue
        k = rng.randint(1, 2)
        ws = []
        rem = 1000
        for i in range(k):
            if i == k - 1:
                ws.append(rem)
            else:
                w = rng.randint(1, rem - 1)
                ws.append(w)
                rem -= w
        bundle = []
        for w in ws:
            p = simple_path(s, d)
            hops += len(p) - 1
            bundle.append({'path': ['R%d' % x for x in p], 'weight': w})
        plan.setdefault('R%d' % s, {})['R%d' % d] = bundle
print('plan hops', hops, file=sys.stderr)

keys = []
capmap = {}
for l in links:
    a, b = l['source'], l['target']
    capmap[(a, b)] = l['capacity']
    capmap[(b, a)] = l['capacity']
for e in ext_ids:
    capmap[(-1, e)] = 10**9
    capmap[(e, -1)] = 10**9
for f in sorted(capmap):
    a, b = f
    if a == -1:
        keys.append('low_R%d_origination' % b)
    elif b == -1:
        keys.append('low_R%d_termination' % a)
    else:
        keys.append('low_R%d_egress_to_R%d' % (a, b))
        keys.append('low_R%d_ingress_from_R%d' % (b, a))

settings = {'trials': TRIALS, 'epsilon': rng.choice([0, 50000]), 'seed': rng.randrange(2**32),
            'cutoff': [1, 2], 'bias': 24000, 'tau': 100000, 'gamma': [1, 2], 'cache_slots': 4}
events = []
for r in range(REPAIRS):
    demands = []
    for s in ext_ids:
        for d in ext_ids:
            if s != d and rng.random() < 0.7:
                demands.append([s, d, rng.randint(0, 1000)])
    counters = {}
    for f in sorted(capmap):
        a, b = f
        if a == -1:
            ks = ['low_R%d_origination' % b]
        elif b == -1:
            ks = ['low_R%d_termination' % a]
        else:
            ks = ['low_R%d_egress_to_R%d' % (a, b), 'low_R%d_ingress_from_R%d' % (b, a)]
        for k in ks:
            if rng.random() < 0.85:
                counters[k] = {'perturbed': rng.randint(0, capmap[f])}
    events.append({'op': 'patch', 'demands': demands, 'counters': counters})
    if r == 0:
        events.append({'op': 'routes', 'label': 'L', 'paths': plan})
    events.append({'op': 'repair', 'id': 'rep%d' % r})
    events.append({'op': 'validate', 'id': 'rep%d' % r})

nflows = len(capmap)
print('flows per repair', nflows, 'total', nflows * REPAIRS, file=sys.stderr)
request = {'streams': [{'topology': topo, 'settings': settings, 'events': events}]}
payload = json.dumps(request, separators=(',', ':')).encode()
print('request bytes', len(payload), file=sys.stderr)
t0 = time.time()
out = M.replay(M.parse_request(payload))
t1 = time.time()
res = out['streams'][0]['events']
print('elapsed %.2fs' % (t1 - t0))
print('repair hits', [e['cache_hit'] for e in res if e['op'] == 'repair'])
print('validate', [ (e['checked'], e['passed'], e['consistent']) for e in res if e['op'] == 'validate'][:3])
d = json.dumps(out, separators=(',', ':'))
print('output bytes', len(d))
import resource
print('maxrss MiB', resource.getrusage(resource.RUSAGE_SELF).ru_maxrss / 1024)
PYEOF
